## 구현 기준

- 최소 금액은 **해당 코드의 대상 상품에 대한 멤버십 할인 전 금액**으로 판단합니다. 실제 프로모션 할인은 멤버십 할인 후 금액에 적용합니다.
- 정률 할인은 라인별로 반올림합니다. 정액 할인만 비례 배분 후 잔액을 조정합니다.
- 순수성을 위해 시스템 시계를 읽지 않습니다. **등록된 코드를 적용할 때는 `today`를 전달해야 합니다.** 문자열은 서울 현지 날짜, `Date`는 서울 날짜로 변환합니다.
- 잘못된 코드는 가격 계산을 막지 않습니다. 잘못된 금액·날짜나 필수 날짜 누락은 호출 계약 위반으로 예외 처리합니다.

## 1. `pricing.ts`

```ts
export type Category = 'grocery' | 'household' | 'alcohol';

export interface LineItem {
  sku: string;
  name: string;
  unitPrice: number;
  qty: number;
  category: Category;
}

export interface Cart {
  items: LineItem[];
  memberTier: 'none' | 'plus';
}

/** 문자열은 YYYY-MM-DD 형식의 Asia/Seoul 현지 날짜 */
export type Today = string | Date;

export type PromoCode = 'FRESH10' | 'SAVE5000' | 'HOME15';

export type PromoFailure =
  | 'unknown'
  | 'expired'
  | 'below_minimum'
  | 'no_eligible_items';

export type PromoResult =
  | { status: 'not_requested' }
  | { status: 'applied'; code: PromoCode }
  | { status: 'rejected'; code: string; reason: PromoFailure };

export interface PricedLine extends LineItem {
  subtotal: number;
  memberDiscount: number;
  promoDiscount: number;
  /** 할인 후 부가세 포함 결제 금액 */
  total: number;
  /** total에 이미 포함된 부가세 */
  tax: number;
}

export interface PricingResult {
  lines: PricedLine[];
  subtotal: number;
  memberDiscount: number;
  promoDiscount: number;
  tax: number;
  total: number;
  promo: PromoResult;
}

type Promotion = {
  eligibleCategories: readonly Category[];
  minimum: number;
  expiresOn: string;
} & (
  | { kind: 'percent'; percent: number }
  | { kind: 'fixed'; amount: number }
);

const PROMOTIONS = {
  FRESH10: {
    kind: 'percent',
    percent: 10,
    eligibleCategories: ['grocery', 'household'],
    minimum: 40_000,
    expiresOn: '2025-12-31',
  },
  SAVE5000: {
    kind: 'fixed',
    amount: 5_000,
    eligibleCategories: ['grocery', 'household'],
    minimum: 25_000,
    expiresOn: '2025-06-30',
  },
  HOME15: {
    kind: 'percent',
    percent: 15,
    eligibleCategories: ['household'],
    minimum: 0,
    expiresOn: '2025-12-31',
  },
} as const satisfies Record<PromoCode, Promotion>;

const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);

function assertNonNegativeInteger(value: number, name: string): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative safe integer`);
  }
}

function toAmount(value: bigint): number {
  if (value < 0n || value > MAX_SAFE) {
    throw new RangeError('Amount exceeds the supported integer range');
  }
  return Number(value);
}

function sum(values: readonly number[]): number {
  return toAmount(values.reduce((acc, value) => acc + BigInt(value), 0n));
}

/** 비음수 유리수를 정확하게 half-up 반올림한다. */
function roundFraction(numerator: bigint, denominator: bigint): number {
  return toAmount(
    (2n * numerator + denominator) / (2n * denominator),
  );
}

function percentage(amount: number, percent: number): number {
  return roundFraction(BigInt(amount) * BigInt(percent), 100n);
}

/**
 * 정액 할인 배분.
 * bases는 멤버십 할인 후 각 대상 라인의 금액이다.
 *
 * 비례액을 라인별 half-up 반올림한 뒤 큰 금액 순으로 잔액을 조정한다.
 * 동액이면 입력 순서가 우선이다.
 * 어느 라인도 음수 할인이나 라인 금액 초과 할인을 받지 않는다.
 */
export function allocateFixedDiscount(
  bases: readonly number[],
  requested: number,
): number[] {
  assertNonNegativeInteger(requested, 'requested');
  bases.forEach((base) => assertNonNegativeInteger(base, 'base'));

  const baseTotal = sum(bases);
  const target = Math.min(requested, baseTotal);

  if (target === 0) {
    return bases.map(() => 0);
  }

  const discounts = bases.map((base) =>
    roundFraction(
      BigInt(target) * BigInt(base),
      BigInt(baseTotal),
    ),
  );

  let residual = target - sum(discounts);

  const order = bases
    .map((base, index) => ({ base, index }))
    .sort((a, b) => b.base - a.base || a.index - b.index);

  for (const { base, index } of order) {
    if (residual === 0) break;

    const adjustment =
      residual > 0
        ? Math.min(residual, base - discounts[index])
        : -Math.min(-residual, discounts[index]);

    discounts[index] += adjustment;
    residual -= adjustment;
  }

  if (residual !== 0) {
    throw new Error('Internal allocation invariant violated');
  }

  return discounts;
}

function seoulDate(today: Today | undefined): string {
  if (today === undefined) {
    throw new TypeError('today is required when using a registered promo code');
  }

  if (typeof today === 'string') {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      throw new RangeError('today must be YYYY-MM-DD');
    }

    const parsed = new Date(`${today}T00:00:00.000Z`);
    if (
      !Number.isFinite(parsed.getTime()) ||
      parsed.toISOString().slice(0, 10) !== today
    ) {
      throw new RangeError('Invalid calendar date');
    }

    return today;
  }

  if (!(today instanceof Date) || !Number.isFinite(today.getTime())) {
    throw new RangeError('Invalid Date');
  }

  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Seoul',
    calendar: 'gregory',
    numberingSystem: 'latn',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    era: 'short',
  }).formatToParts(today);

  const part = (type: Intl.DateTimeFormatPartTypes): string =>
    parts.find((p) => p.type === type)!.value;

  const year = part('year');
  if (part('era') !== 'AD' || year.length > 4) {
    throw new RangeError('Unsupported calendar year');
  }

  return `${year.padStart(4, '0')}-${part('month')}-${part('day')}`;
}

function findPromotion(code: string): Promotion | undefined {
  return Object.hasOwn(PROMOTIONS, code)
    ? PROMOTIONS[code as PromoCode]
    : undefined;
}

export function priceCart(
  cart: Cart,
  promoCode?: string,
  today?: Today,
): PricingResult {
  if (cart.memberTier !== 'none' && cart.memberTier !== 'plus') {
    throw new TypeError('Invalid member tier');
  }
  if (promoCode !== undefined && typeof promoCode !== 'string') {
    throw new TypeError('promoCode must be one string');
  }

  // 새 객체만 생성하며 cart, items, today를 변경하지 않는다.
  const lines: PricedLine[] = cart.items.map((item) => {
    assertNonNegativeInteger(item.unitPrice, 'unitPrice');
    assertNonNegativeInteger(item.qty, 'qty');

    if (
      item.category !== 'grocery' &&
      item.category !== 'household' &&
      item.category !== 'alcohol'
    ) {
      throw new TypeError('Invalid category');
    }

    const subtotal = toAmount(BigInt(item.unitPrice) * BigInt(item.qty));
    const memberDiscount =
      cart.memberTier === 'plus' && item.category !== 'alcohol'
        ? percentage(subtotal, 5)
        : 0;

    return {
      ...item,
      subtotal,
      memberDiscount,
      promoDiscount: 0,
      total: subtotal - memberDiscount,
      tax: 0,
    };
  });

  // 총액도 안전한 정수 범위를 벗어나지 않도록 검사한다.
  const subtotal = sum(lines.map((line) => line.subtotal));
  const memberDiscount = sum(lines.map((line) => line.memberDiscount));

  const code = promoCode?.trim().toUpperCase() ?? '';
  let promo: PromoResult = { status: 'not_requested' };

  if (code !== '') {
    const definition = findPromotion(code);

    const reject = (reason: PromoFailure): PromoResult => ({
      status: 'rejected',
      code,
      reason,
    });

    if (!definition) {
      promo = reject('unknown');
    } else if (seoulDate(today) > definition.expiresOn) {
      promo = reject('expired');
    } else {
      const eligibleIndices = lines.flatMap((line, index) =>
        line.category !== 'alcohol' &&
        definition.eligibleCategories.includes(line.category) &&
        line.total > 0
          ? [index]
          : [],
      );

      const qualifyingAmount = sum(
        eligibleIndices.map((index) => lines[index].subtotal),
      );

      if (eligibleIndices.length === 0) {
        promo = reject('no_eligible_items');
      } else if (qualifyingAmount < definition.minimum) {
        promo = reject('below_minimum');
      } else {
        const bases = eligibleIndices.map((index) => lines[index].total);

        const discounts =
          definition.kind === 'fixed'
            ? allocateFixedDiscount(bases, definition.amount)
            : bases.map((base) => percentage(base, definition.percent));

        eligibleIndices.forEach((index, position) => {
          lines[index].promoDiscount = discounts[position];
          lines[index].total -= discounts[position];
        });

        promo = { status: 'applied', code: code as PromoCode };
      }
    }
  }

  for (const line of lines) {
    line.tax =
      line.category === 'grocery'
        ? 0
        : roundFraction(BigInt(line.total) * 10n, 110n);
  }

  return {
    lines,
    subtotal,
    memberDiscount,
    promoDiscount: sum(lines.map((line) => line.promoDiscount)),
    tax: sum(lines.map((line) => line.tax)),
    total: sum(lines.map((line) => line.total)),
    promo,
  };
}
```

## 2. `pricing.test.ts`

```ts
import { describe, expect, it } from 'vitest';
import {
  allocateFixedDiscount,
  priceCart,
  type Cart,
  type Category,
  type LineItem,
  type PricingResult,
} from './pricing';

function item(
  unitPrice: number,
  category: Category = 'grocery',
  qty = 1,
  sku = 'sku',
): LineItem {
  return { sku, name: sku, unitPrice, qty, category };
}

function cart(
  items: LineItem[],
  memberTier: Cart['memberTier'] = 'none',
): Cart {
  return { items, memberTier };
}

function expectBalanced(result: PricingResult): void {
  for (const key of [
    'subtotal',
    'memberDiscount',
    'promoDiscount',
    'tax',
    'total',
  ] as const) {
    expect(result[key]).toBe(
      result.lines.reduce((total, line) => total + line[key], 0),
    );
    expect(Number.isSafeInteger(result[key])).toBe(true);
  }

  expect(result.total).toBe(
    result.subtotal - result.memberDiscount - result.promoDiscount,
  );

  for (const line of result.lines) {
    expect(line.total).toBe(
      line.subtotal - line.memberDiscount - line.promoDiscount,
    );
    for (const value of [
      line.subtotal,
      line.memberDiscount,
      line.promoDiscount,
      line.total,
      line.tax,
    ]) {
      expect(Number.isSafeInteger(value)).toBe(true);
      expect(value).toBeGreaterThanOrEqual(0);
    }
  }
}

describe('priceCart', () => {
  it('빈 장바구니와 코드 미입력을 처리한다', () => {
    expect(priceCart(cart([]))).toEqual({
      lines: [],
      subtotal: 0,
      memberDiscount: 0,
      promoDiscount: 0,
      tax: 0,
      total: 0,
      promo: { status: 'not_requested' },
    });

    expect(priceCart(cart([]), '  ').promo).toEqual({
      status: 'not_requested',
    });
  });

  it('면세/과세를 구분하고 포함된 VAT만 분리한다', () => {
    const result = priceCart(cart([
      item(1_100, 'grocery'),
      item(1_100, 'household'),
      item(1_100, 'alcohol'),
    ]));

    expect(result.lines.map((line) => line.tax)).toEqual([0, 100, 100]);
    expect(result.tax).toBe(200);
    expect(result.total).toBe(3_300);
    expectBalanced(result);
  });

  it.each([
    [5, 0],
    [6, 1],
    [16, 1],
    [17, 2],
  ])('과세 라인 %i원의 VAT는 %i원이다', (amount, tax) => {
    expect(
      priceCart(cart([item(amount, 'household')])).tax,
    ).toBe(tax);
  });

  it('VAT를 합산 금액이 아니라 각 라인에서 반올림한다', () => {
    const result = priceCart(cart([
      item(6, 'household'),
      item(6, 'household'),
    ]));

    expect(result.tax).toBe(2); // round(12 / 11) = 1과 다름
  });

  it('Plus 할인은 수량을 곱한 라인 금액에서 half-up 반올림한다', () => {
    const result = priceCart(cart([
      item(1_990, 'grocery', 3),
      item(9),
      item(10),
    ], 'plus'));

    expect(result.lines.map((line) => line.memberDiscount))
      .toEqual([299, 0, 1]);
    expectBalanced(result);
  });

  it('최소 금액은 할인 전, 프로모션은 멤버십 할인 후에 적용한다', () => {
    const result = priceCart(
      cart([item(40_000)], 'plus'),
      ' fresh10 ',
      '2025-12-31',
    );

    expect(result.promo).toEqual({
      status: 'applied',
      code: 'FRESH10',
    });
    expect(result.memberDiscount).toBe(2_000);
    expect(result.promoDiscount).toBe(3_800);
    expect(result.total).toBe(34_200);
    expectBalanced(result);
  });

  it.each([
    ['FRESH10', 39_999, '2025-12-31', 'rejected'],
    ['FRESH10', 40_000, '2025-12-31', 'applied'],
    ['SAVE5000', 24_999, '2025-06-30', 'rejected'],
    ['SAVE5000', 25_000, '2025-06-30', 'applied'],
  ] as const)(
    '%s 최소 금액 경계: %i원',
    (code, amount, today, status) => {
      const result = priceCart(cart([item(amount)]), code, today);
      expect(result.promo.status).toBe(status);

      if (status === 'rejected') {
        expect(result.promo).toMatchObject({ reason: 'below_minimum' });
      }
    },
  );

  it.each([
    ['FRESH10', '2025-12-31', '2026-01-01'],
    ['SAVE5000', '2025-06-30', '2025-07-01'],
    ['HOME15', '2025-12-31', '2026-01-01'],
  ] as const)('%s 만료일은 포함한다', (code, lastDay, nextDay) => {
    const input = cart([item(50_000, 'household')]);

    expect(priceCart(input, code, lastDay).promo.status).toBe('applied');
    expect(priceCart(input, code, nextDay).promo).toMatchObject({
      status: 'rejected',
      reason: 'expired',
    });
  });

  it('UTC가 아닌 서울 자정에서 만료된다', () => {
    const input = cart([item(25_000)]);

    expect(priceCart(
      input,
      'SAVE5000',
      new Date('2025-06-30T14:59:59.999Z'),
    ).promo.status).toBe('applied');

    expect(priceCart(
      input,
      'SAVE5000',
      new Date('2025-06-30T15:00:00.000Z'),
    ).promo).toMatchObject({ reason: 'expired' });
  });

  it('HOME15는 생활용품에만 적용하고 멤버십 뒤에 계산한다', () => {
    const result = priceCart(cart([
      item(100, 'household'),
      item(100, 'grocery'),
      item(100, 'alcohol'),
    ], 'plus'), 'HOME15', '2025-07-02');

    expect(result.lines.map((line) => line.memberDiscount))
      .toEqual([5, 5, 0]);
    expect(result.lines.map((line) => line.promoDiscount))
      .toEqual([14, 0, 0]); // 95 × 15% = 14.25
    expect(result.lines.map((line) => line.tax)).toEqual([7, 0, 9]);
    expectBalanced(result);
  });

  it('정률 프로모션도 라인별 half-up 반올림한다', () => {
    const result = priceCart(cart([
      item(3, 'household'),
      item(10, 'household'),
    ]), 'HOME15', '2025-07-02');

    expect(result.lines.map((line) => line.promoDiscount))
      .toEqual([0, 2]); // 0.45 → 0, 1.5 → 2
  });

  it.each(['FRESH10', 'SAVE5000', 'HOME15'])(
    '%s와 Plus 모두 주류를 할인하지 않는다',
    (code) => {
      const result = priceCart(cart([
        item(50_000, 'household'),
        item(99_000, 'alcohol'),
      ], 'plus'), code, '2025-06-30');

      expect(result.promo.status).toBe('applied');
      expect(result.lines[1]).toMatchObject({
        memberDiscount: 0,
        promoDiscount: 0,
        total: 99_000,
        tax: 9_000,
      });
      expectBalanced(result);
    },
  );

  it('주류 금액은 최소 금액에 포함하지 않는다', () => {
    const result = priceCart(cart([
      item(39_999),
      item(100_000, 'alcohol'),
    ]), 'FRESH10', '2025-07-02');

    expect(result.promo).toMatchObject({ reason: 'below_minimum' });
  });

  it('정액 할인은 멤버십 후 금액 비율로 배분하고 VAT에도 반영한다', () => {
    const result = priceCart(cart([
      item(10_000, 'grocery'),
      item(15_000, 'household'),
      item(11_000, 'alcohol'),
    ], 'plus'), 'SAVE5000', '2025-06-30');

    expect(result.lines.map((line) => line.memberDiscount))
      .toEqual([500, 750, 0]);
    expect(result.lines.map((line) => line.promoDiscount))
      .toEqual([2_000, 3_000, 0]);
    expect(result.lines.map((line) => line.total))
      .toEqual([7_500, 11_250, 11_000]);
    expect(result.lines.map((line) => line.tax))
      .toEqual([0, 1_023, 1_000]);
    expectBalanced(result);
  });

  const rejectedCases = [
    {
      code: 'NOT_REAL',
      today: '2025-07-02',
      input: cart([item(50_000, 'household')], 'plus'),
      reason: 'unknown',
    },
    {
      code: 'SAVE5000',
      today: '2025-07-02',
      input: cart([item(50_000, 'household')], 'plus'),
      reason: 'expired',
    },
    {
      code: 'FRESH10',
      today: '2025-07-02',
      input: cart([item(39_999, 'household')], 'plus'),
      reason: 'below_minimum',
    },
    {
      code: 'HOME15',
      today: '2025-07-02',
      input: cart([item(50_000, 'grocery')], 'plus'),
      reason: 'no_eligible_items',
    },
  ] as const;

  it.each(rejectedCases)(
    '$reason이면 프로모션 없는 가격을 그대로 반환한다',
    ({ input, code, today, reason }) => {
      const result = priceCart(input, code, today);
      const baseline = priceCart(input);

      expect(result.promo).toEqual({
        status: 'rejected',
        code,
        reason,
      });
      expect({ ...result, promo: baseline.promo }).toEqual(baseline);
    },
  );

  it.each([
    cart([]),
    cart([item(10_000, 'alcohol')]),
    cart([item(0, 'household')]),
    cart([item(1_000, 'household', 0)]),
  ])('양수인 대상 라인이 없으면 no_eligible_items이다', (input) => {
    expect(
      priceCart(input, 'FRESH10', '2025-07-02').promo,
    ).toMatchObject({ reason: 'no_eligible_items' });
  });

  it('여러 코드가 들어간 문자열은 하나의 unknown 코드로 취급한다', () => {
    expect(priceCart(
      cart([item(50_000)]),
      'FRESH10,SAVE5000',
      '2025-06-30',
    ).promo).toMatchObject({ reason: 'unknown' });
  });

  it('Object prototype의 속성을 코드로 인식하지 않는다', () => {
    expect(
      priceCart(cart([]), '__proto__').promo,
    ).toMatchObject({ reason: 'unknown' });
  });

  it('사유 우선순위는 expired → no_eligible_items → below_minimum이다', () => {
    expect(priceCart(
      cart([]), 'SAVE5000', '2025-07-02',
    ).promo).toMatchObject({ reason: 'expired' });

    expect(priceCart(
      cart([]), 'FRESH10', '2025-07-02',
    ).promo).toMatchObject({ reason: 'no_eligible_items' });
  });

  it('입력을 변경하지 않고 같은 입력에는 같은 결과를 반환한다', () => {
    const input = cart([item(50_000, 'household')], 'plus');
    const snapshot = structuredClone(input);
    const today = new Date('2025-07-02T00:00:00Z');
    const timestamp = today.getTime();

    const first = priceCart(input, 'HOME15', today);
    expect(priceCart(input, 'HOME15', today)).toEqual(first);
    expect(input).toEqual(snapshot);
    expect(today.getTime()).toBe(timestamp);
  });

  it('등록된 코드에는 날짜 입력이 필요하다', () => {
    expect(() =>
      priceCart(cart([item(50_000)]), 'FRESH10'),
    ).toThrow(TypeError);

    expect(() => priceCart(cart([]))).not.toThrow();
    expect(() => priceCart(cart([]), 'UNKNOWN')).not.toThrow();
  });

  it.each([
    '2025-02-29',
    '2025-13-01',
    '2025-7-2',
    new Date('invalid'),
  ])('잘못된 날짜를 거부한다: %s', (today) => {
    expect(() =>
      priceCart(cart([item(50_000)]), 'FRESH10', today),
    ).toThrow(RangeError);
  });

  it.each([-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1])(
    '잘못된 단가를 거부한다: %s',
    (unitPrice) => {
